package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"net/url"

	wruntime "github.com/wailsapp/wails/v2/pkg/runtime"
)

// Public, fixed product links generated by the store's promotion-link API.
// No shop login credentials or tokens are bundled in the application.
//
//go:embed frontend/src/shop-products.json
var shopProductsJSON []byte

type shopProduct struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	URL    string `json:"url"`
	Source string `json:"source"`
}

func shopProductURL(id string) (string, error) {
	var products []shopProduct
	if err := json.Unmarshal(shopProductsJSON, &products); err != nil {
		return "", err
	}
	for _, p := range products {
		if p.ID != id {
			continue
		}
		u, err := url.Parse(p.URL)
		if err != nil || u.Scheme != "https" || (u.Host != "wxmpurl.cn" && u.Host != "wxaurl.cn") || u.User != nil {
			return "", fmt.Errorf("商品购买链接不可用")
		}
		return p.URL, nil
	}
	return "", fmt.Errorf("商品不在推荐列表中")
}

func (a *Desktop) OpenShopProduct(id string) error {
	link, err := shopProductURL(id)
	if err != nil {
		return err
	}
	wruntime.BrowserOpenURL(a.ctx, link)
	return nil
}

func (a *Desktop) CopyShopProductLink(id string) error {
	link, err := shopProductURL(id)
	if err != nil {
		return err
	}
	return wruntime.ClipboardSetText(a.ctx, link)
}
